/*
 * The one way a library item is written. Every field is checked here, on the server,
 * because a page is only the caller's word.
 *  - brief: Markdown, kept as typed. Pages render it with HTML switched off
 *    (Shell/Formatted text), so a tag in it shows as text and never runs.
 *  - resources: a link must be http(s). A file must be one THIS coach uploaded
 *    (_Files.owner, written by the backend from the uploader's session), or one already
 *    on this item: otherwise a learner's private hand-in could be attached here and handed
 *    to every learner who later gets this homework.
 *  - Editing never reaches a plan: steps hold their own copy (SCOPE R4).
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const id = String(Inputs.id || '').trim();

    let existing = null;
    if (id) {
      const found = await R.query('LibraryItem', { objectId: { equalTo: id } }, { limit: 2, plain: true });
      if (found.length !== 1) return refuse('That homework is no longer in the library. Reload the page.');
      existing = found[0];
    }

    const title = String(Inputs.title || '').trim().replace(/\s+/g, ' ');
    if (!title) return refuse('Give the homework a title.');
    if (title.length > 140) return refuse('Keep the title under 140 characters.');

    const brief = String(Inputs.brief || '').replace(/\r\n/g, '\n').trim();
    if (brief.length > 20000) return refuse('The brief is too long. Keep it under 20,000 characters, or put the rest in a resource.');

    const rawList = Inputs.handInChecklist === undefined || Inputs.handInChecklist === null ? [] : Inputs.handInChecklist;
    if (!Array.isArray(rawList)) return refuse('The hand-in list could not be read. Reload the page and try again.');
    const handInChecklist = rawList
      .map((c) => (typeof c === 'string' ? { text: c, required: true } : { text: String((c && c.text) || ''), required: !(c && c.required === false) }))
      .map((c) => ({ text: c.text.trim().replace(/\s+/g, ' '), required: c.required }))
      .filter((c) => c.text);
    if (handInChecklist.length > 30) return refuse('Keep the hand-in list to 30 items or fewer.');
    if (handInChecklist.some((c) => c.text.length > 300)) return refuse('Keep each hand-in item under 300 characters.');

    const rawRes = Inputs.resources === undefined || Inputs.resources === null ? [] : Inputs.resources;
    if (!Array.isArray(rawRes)) return refuse('The resources could not be read. Reload the page and try again.');
    if (rawRes.length > 20) return refuse('Keep the resources to 20 or fewer.');
    const onItem = new Set(((existing && existing.resources) || []).filter((r) => r && r.file).map((r) => r.file));
    const resources = [];
    for (const r of rawRes) {
      if (!r || typeof r !== 'object') return refuse('A resource could not be read. Remove it and add it again.');
      const label = String(r.label || '').trim().replace(/\s+/g, ' ');
      if (label.length > 200) return refuse('Keep each resource label under 200 characters.');
      if (r.file) {
        const file = String(r.file);
        if (!onItem.has(file)) {
          const rows = await R.query('_Files', { storedName: { equalTo: file } }, { limit: 2, plain: true });
          const owner = rows.length === 1 ? rows[0].owner : null;
          const ownerId = owner && typeof owner === 'object' ? owner.objectId : owner;
          if (ownerId !== me) return refuse('One of the files is not one you uploaded. Remove it and upload it again.');
        }
        const fileName = String(r.fileName || '').trim();
        resources.push({ label: label || fileName || 'File', file, fileName });
      } else {
        const url = String(r.url || '').trim();
        if (!url && !label) continue;
        let parsed = null;
        try { parsed = new URL(url); } catch (e) { parsed = null; }
        if (!parsed || (parsed.protocol !== 'https:' && parsed.protocol !== 'http:')) {
          return refuse('"' + (url || label) + '" is not a web address. Links start with https://');
        }
        resources.push({ label: label || parsed.hostname, url: parsed.href });
      }
    }

    const rawTags = Inputs.tags === undefined || Inputs.tags === null ? [] : Inputs.tags;
    const tagList = Array.isArray(rawTags) ? rawTags : String(rawTags).split(',');
    const tags = [];
    for (const t of tagList) {
      const tag = String(t || '').trim().replace(/\s+/g, ' ');
      if (tag && !tags.some((x) => x.toLowerCase() === tag.toLowerCase())) tags.push(tag);
    }
    if (tags.length > 12) return refuse('Keep it to 12 tags or fewer.');
    if (tags.some((t) => t.length > 40)) return refuse('Keep each tag under 40 characters.');

    const m = Inputs.estimatedMinutes;
    let estimatedMinutes = null;
    if (m !== undefined && m !== null && String(m).trim() !== '') {
      estimatedMinutes = Number(String(m).trim());
      if (!Number.isInteger(estimatedMinutes) || estimatedMinutes < 1 || estimatedMinutes > 6000) {
        return refuse('Give the estimated time as a whole number of minutes, or leave it empty.');
      }
    }

    const fields = { title, brief, handInChecklist, resources, tags, estimatedMinutes };
    if (existing) {
      await R.save(existing.objectId, fields, { className: 'LibraryItem' });
      Outputs.id = existing.objectId;
      Outputs.created = false;
    } else {
      const row = await R.create('LibraryItem', Object.assign({ archived: false }, fields), { plain: true });
      Outputs.id = row.objectId || row.id;
      Outputs.created = true;
    }
    Outputs.done();
  } catch (e) {
    console.error('[dbu:saveLibraryItem]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
